Problem:
A researcher is transporting their arsenal of imaging systems using two different methods, by delivery truck and by van. Transporting by delivery truck takes 12 hours and costs $300 per trip. Transporting by van takes 10 hours and costs $200 per trip. The researcher needs to transport 20 trips worth of equipment and has a budget of $5500. Additionally, the number of transports by the delivery truck must be less than the number of transports by van. How many of each transportation method should they use to minimize the total number of hours spent on delivery?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "delivery truck transports",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "van transports",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "delivery truck transports",
     "coef": 12.0
    },
    {
     "var": "van transports",
     "coef": 10.0
    }
   ]
  },
  "constraints": [
   {
    "name": "trips_required",
    "terms": [
     {
      "var": "delivery truck transports",
      "coef": 1.0
     },
     {
      "var": "van transports",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 20.0
   },
   {
    "name": "budget",
    "terms": [
     {
      "var": "delivery truck transports",
      "coef": 300.0
     },
     {
      "var": "van transports",
      "coef": 200.0
     }
    ],
    "sense": "<=",
    "rhs": 5500.0
   },
   {
    "name": "truck_fewer_than_van",
    "terms": [
     {
      "var": "delivery truck transports",
      "coef": 1.0
     },
     {
      "var": "van transports",
      "coef": -1.0
     }
    ],
    "sense": "<=",
    "rhs": -1.0
   }
  ]
 },
 "facts": {
  "objective": 200.0,
  "values": {
   "delivery truck transports": 0.0,
   "van transports": 20.0
  },
  "binding": [
   "trips_required"
  ],
  "slack": {
   "trips_required": 0.0,
   "budget": 1500.0,
   "truck_fewer_than_van": 19.0
  },
  "shadow_prices": null,
  "limits": {
   "trips_required": {
    "dropped_improves": true,
    "loosened_improves": true
   },
